mapper.select:
SELECT 
FROM CODEF_CONNECTION
WHERE MEMBER_ID = #{memberId}
  AND ORGANIZATION = #{organization}

mapper.update:
UPDATE CODEF_CONNECTION
SET VERIFIED_YN            = 'Y',
    VERIFIED_ACCOUNT_ENC   = #{verifiedAccountEnc},
    VERIFIED_ACCOUNT_LAST4 = #{verifiedAccountLast4},
    VERIFIED_HOLDER_NAME   = #{verifiedHolderName},
    KEY_VER                = #{keyVer},
    VERIFIED_AT            = #{verifiedAt, jdbcType=TIMESTAMP},
    UPDATED_AT             = #{verifiedAt, jdbcType=TIMESTAMP}
WHERE MEMBER_ID = #{memberId}
  AND ORGANIZATION = #{organization}

mapper.delete:
DELETE FROM CODEF_CONNECTION
WHERE MEMBER_ID = #{memberId}
  AND ORGANIZATION = #{organization}
